<?php
namespace App\Domain\Fiscal;
use App\Domain\Audit\AuditRecorder;use App\Domain\Tenancy\CurrentOrganization;use App\Models\{FiscalDocument,FiscalDocumentNumber,User};use Carbon\CarbonImmutable;use DomainException;use Illuminate\Support\Facades\DB;
final class FiscalDocumentNumberManager { public function __construct(private readonly CurrentOrganization $currentOrganization,private readonly AuditRecorder $audit){}
 public function assign(FiscalDocument $document,User $actor):FiscalDocumentNumber { $org=$this->organization($actor);return DB::transaction(function()use($document,$actor,$org){$doc=FiscalDocument::query()->forOrganization($org)->with('pointOfSale')->lockForUpdate()->find($document->id);if(!$doc||!$doc->pointOfSale){throw new DomainException('El documento no pertenece a la organización activa.');}$existing=FiscalDocumentNumber::query()->where('fiscal_document_id',$doc->id)->lockForUpdate()->first();if($existing){return $existing;} $point=$doc->pointOfSale;$last=(int)FiscalDocumentNumber::query()->where('fiscal_point_of_sale_id',$point->id)->where('environment',$point->environment->value)->lockForUpdate()->max('number');$number=FiscalDocumentNumber::query()->create(['organization_id'=>$org,'fiscal_document_id'=>$doc->id,'fiscal_point_of_sale_id'=>$point->id,'environment'=>$point->environment->value,'number'=>$last+1,'assigned_at'=>CarbonImmutable::now(),'assigned_by_user_id'=>$actor->id]);$this->audit->record($number,'fiscal_document_number_assigned',null,['fiscal_document_id'=>$doc->id,'number'=>$number->number,'environment'=>$point->environment->value]);return $number;},3);}
 private function organization(User $actor):int{$id=$this->currentOrganization->id($actor);if(!($this->currentOrganization->roleFor($actor)?->canManageOrganization()??false)){throw new DomainException('Sólo un administrador puede asignar numeración fiscal.');}return $id;}}
